#!/usr/bin/env python3
"""Build eight explicitly themed guardian appearance prototypes.

AI-generated source materials are transformed into face-specific UV atlases,
with per-realm silhouettes, individually jointed legs and distinctive bones.
Only the listed eight models and 24 maps are touched. No gameplay or balance.
--check compares generated bytes; --write must be explicit. Pillow required.
"""
import argparse, io, json, math, random
from pathlib import Path
from PIL import Image, ImageChops, ImageDraw, ImageEnhance, ImageFilter

ROOT=Path(__file__).resolve().parents[1]
RP=ROOT/'Hakkai_v7.1.0/ResourcePack'
BASE=ROOT/'tools/art_templates/mob_baselines'
MATERIAL=ROOT/'tools/art_templates/guardian_materials'
SIZE=1024
# Each design specifies hand-placed geometry attached to existing animated bones.
# Coordinates are in Bedrock model units. Each existing joint is renamed
# per creature; compatible animations are generated separately.
def c(origin,size):return {'origin':origin,'size':size}
